use crate::{capture, config::AppConfig, input, vision::{self, Match, Template}, window::{self, GameWindow}};
use eframe::egui::{self, Color32, ColorImage, TextureHandle, TextureOptions};
use image::RgbaImage;
use std::{sync::mpsc::{self, Receiver}, time::Instant};

enum Work { Captured(isize, Result<RgbaImage,String>), Found(Result<Option<Match>,String>) }
pub struct UmaPilotApp {
    config: AppConfig, windows: Vec<GameWindow>, selected_window: Option<usize>, templates: Vec<Template>, selected_template: Option<usize>, screenshot: Option<RgbaImage>, screenshot_window: Option<isize>, captured_at: Option<Instant>, texture: Option<TextureHandle>, hit: Option<Match>, status: String, logs: Vec<String>, real_click: bool, confirm_click: bool, worker: Option<Receiver<Work>>,
}
impl UmaPilotApp {
    pub fn new(_: &eframe::CreationContext<'_>, config: AppConfig) -> Self { window::enable_dpi_awareness(); let mut app=Self { config, windows:vec![],selected_window:None,templates:vec![],selected_template:None,screenshot:None,screenshot_window:None,captured_at:None,texture:None,hit:None,status:"Ready. Select a window and capture it.".into(),logs:vec![],real_click:false,confirm_click:false,worker:None }; app.refresh_windows(); app.load_templates(); app }
    fn log(&mut self, text: impl Into<String>) { let value=text.into(); tracing::info!("{value}"); self.logs.push(value); if self.logs.len()>100 { self.logs.remove(0); } }
    fn refresh_windows(&mut self) { match window::windows() { Ok(items)=>{ self.windows=items; self.selected_window=None; self.status=format!("Found {} visible windows.",self.windows.len()); }, Err(e)=>self.status=e.to_string() } }
    fn load_templates(&mut self) { match vision::load_templates(&self.config.template_directory) { Ok(items)=>{self.templates=items;self.selected_template=None;self.status=format!("Loaded {} PNG template(s).",self.templates.len());},Err(e)=>self.status=e.to_string()} }
    fn selected_game(&self)->Option<GameWindow>{ self.selected_window.and_then(|i|self.windows.get(i)).cloned() }
    fn start_capture(&mut self) { let Some(game)=self.selected_game() else {self.status="Select a valid window first.".into();return}; if self.worker.is_some(){return} let hwnd=game.hwnd;let(tx,rx)=mpsc::channel(); self.worker=Some(rx);self.status="Capturing client area…".into();std::thread::spawn(move||{let _=tx.send(Work::Captured(hwnd,capture::capture(&game).map_err(|e|e.to_string())));}); }
    fn start_find(&mut self) { let (Some(image),Some(template))=(self.screenshot.clone(),self.selected_template.and_then(|i|self.templates.get(i)).cloned()) else {self.status="Capture/load an image and select a template.".into();return};if self.worker.is_some(){return}let threshold=self.config.confidence_threshold;let(tx,rx)=mpsc::channel();self.worker=Some(rx);self.status="Finding template…".into();std::thread::spawn(move||{let _=tx.send(Work::Found(vision::find(&image,&template,threshold).map_err(|e|e.to_string())));}); }
    fn open_screenshot(&mut self, ctx: &egui::Context) { let Some(path)=rfd::FileDialog::new().add_filter("PNG image", &["png"]).pick_file() else{return};match image::open(&path) { Ok(value)=>{self.screenshot=Some(value.to_rgba8());self.screenshot_window=None;self.captured_at=None;self.hit=None;self.update_texture(ctx);self.status=format!("Loaded offline image {}",path.display());self.log(self.status.clone());},Err(e)=>self.status=format!("Could not load image: {e}") } }
    fn update_texture(&mut self, ctx:&egui::Context) { if let Some(image)=&self.screenshot { let size=[image.width() as usize,image.height() as usize];let color=ColorImage::from_rgba_unmultiplied(size,image.as_raw());self.texture=Some(ctx.load_texture("screenshot",color,TextureOptions::LINEAR)); } }
    fn poll(&mut self,ctx:&egui::Context){let result=self.worker.as_ref().and_then(|rx|rx.try_recv().ok());if let Some(work)=result {self.worker=None;match work {Work::Captured(hwnd,Ok(image))=>{self.screenshot=Some(image);self.screenshot_window=Some(hwnd);self.captured_at=Some(Instant::now());self.hit=None;self.update_texture(ctx);self.status="Capture succeeded.".into();self.log("Captured selected window client area.");},Work::Captured(_,Err(e))=>{self.status=format!("Capture failed: {e}");self.log(self.status.clone());},Work::Found(Ok(Some(hit)))=>{self.status=format!("FOUND: {:.1}% at {}, {}",hit.confidence*100.,hit.x,hit.y);self.log(self.status.clone());self.hit=Some(hit);},Work::Found(Ok(None))=>{self.hit=None;self.status="NOT FOUND: no result meets confidence threshold.".into();self.log(self.status.clone());},Work::Found(Err(e))=>{self.status=format!("Find failed: {e}");self.log(self.status.clone());}}}}
    fn save(&mut self){let Some(image)=&self.screenshot else {self.status="Nothing to save.".into();return};let name=format!("capture_{}.png",chrono_name());let path=self.config.screenshot_directory.join(name);match image.save(&path){Ok(_)=>{self.status=format!("Saved {}",path.display());self.log(self.status.clone());},Err(e)=>self.status=format!("Save failed: {e}")}}
    fn test_click(&mut self){let(Some(game),Some(hit),Some(image),Some(template),Some(at))=(self.selected_game(),self.hit.clone(),self.screenshot.as_ref(),self.selected_template.and_then(|i|self.templates.get(i)),self.captured_at)else{self.status="A valid target window and accepted match are required.".into();return};if self.screenshot_window!=Some(game.hwnd)||at.elapsed().as_secs()>30{self.status="Click blocked: screenshot is stale or belongs to another window. Capture again.".into();return}let verified=vision::find(image,template,self.config.confidence_threshold).ok().flatten();if verified.as_ref()!=Some(&hit){self.status="Click blocked: template no longer verifies against the screenshot.".into();return}match input::target_point(&game,&hit){Err(e)=>self.status=format!("Click blocked: {e}"),Ok(point) if !self.real_click=>{self.status=format!("DRY RUN: would click {}, {}",point.0,point.1);self.log(format!("dry-run click at {:?}; confidence {:.3}",point,hit.confidence));},Ok(point) if !self.confirm_click=>self.status="Enable confirmation before sending a real click.".into(),Ok(point)=>match input::click_once(point){Ok(_)=>{self.status=format!("Clicked {}, {} once.",point.0,point.1);self.log(format!("real click at {:?}; confidence {:.3}",point,hit.confidence));self.confirm_click=false;},Err(e)=>self.status=format!("Click failed: {e}")}}}
}
fn chrono_name()->String { use std::time::{SystemTime,UNIX_EPOCH};SystemTime::now().duration_since(UNIX_EPOCH).map(|d|d.as_secs().to_string()).unwrap_or_else(|_|"capture".into()) }
impl eframe::App for UmaPilotApp { fn update(&mut self,ctx:&egui::Context,_:&mut eframe::Frame){self.poll(ctx);egui::SidePanel::left("controls").min_width(280.).show(ctx,|ui|{ui.heading("UmaPilot");if ui.button("Refresh Windows").clicked(){self.refresh_windows()}ui.label("Target window");egui::ComboBox::from_id_salt("window").selected_text(self.selected_window.and_then(|i|self.windows.get(i)).map(ToString::to_string).unwrap_or_else(||"Choose window…".into())).show_ui(ui,|ui|for(i,w)in self.windows.iter().enumerate(){ui.selectable_value(&mut self.selected_window,Some(i),w.to_string());});if ui.button("Capture Screenshot").clicked(){self.start_capture()}if ui.button("Open Screenshot PNG").clicked(){self.open_screenshot(ctx)}ui.separator();if ui.button("Load Templates").clicked(){self.load_templates()}ui.label("Template");egui::ComboBox::from_id_salt("template").selected_text(self.selected_template.and_then(|i|self.templates.get(i)).and_then(|t|t.path.file_name()).map(|x|x.to_string_lossy().to_string()).unwrap_or_else(||"Choose template…".into())).show_ui(ui,|ui|for(i,t)in self.templates.iter().enumerate(){let name=t.path.file_name().map(|n|n.to_string_lossy()).unwrap_or_else(||"unnamed".into());ui.selectable_value(&mut self.selected_template,Some(i),name);});ui.add(egui::Slider::new(&mut self.config.confidence_threshold,0.50..=1.0).text("Confidence"));if ui.button("Find Template").clicked(){self.start_find()}if ui.button("Save Screenshot").clicked(){self.save()}ui.separator();ui.checkbox(&mut self.real_click,"Real Click (off = Dry Run)");if self.real_click{ui.checkbox(&mut self.confirm_click,"I confirm one real click");}if ui.button("Test Click").clicked(){self.test_click()};});egui::CentralPanel::default().show(ctx,|ui|{ui.heading("Screenshot preview");if let Some(tex)=&self.texture {let available=ui.available_size();let mut size=tex.size_vec2();let scale=(available.x/size.x).min((available.y-40.)/size.y).min(1.);size*=scale;let response=ui.add(egui::Image::new(tex).fit_to_exact_size(size));if let Some(hit)=&self.hit {let rect=egui::Rect::from_min_size(response.rect.min+egui::vec2(hit.x as f32*scale,hit.y as f32*scale),egui::vec2(hit.width as f32*scale,hit.height as f32*scale));ui.painter().rect_stroke(rect,0.,egui::Stroke::new(2.,Color32::LIME),egui::StrokeKind::Outside);}}else{ui.label("No screenshot captured yet.");}});egui::TopBottomPanel::bottom("status").resizable(true).default_height(145.).show(ctx,|ui|{ui.colored_label(if self.status.contains("failed")||self.status.contains("NOT FOUND"){Color32::LIGHT_RED}else{Color32::LIGHT_GREEN},&self.status);if let Some(hit)=&self.hit{ui.label(format!("Match: x={}, y={}, w={}, h={}, confidence={:.2}%",hit.x,hit.y,hit.width,hit.height,hit.confidence*100.));}ui.separator();egui::ScrollArea::vertical().show(ui,|ui|for line in self.logs.iter().rev().take(12){ui.monospace(line);});});if self.worker.is_some(){ctx.request_repaint();}} }
